# Terraform Module: S3 + RDS + IAM for Dev/Prod

Below is a complete, production-ready Terraform implementation supporting dev and prod environments via tfvars files.

## Directory Structure

```
.
├── main.tf
├── variables.tf
├── outputs.tf
├── terraform.tfvars
├── dev.tfvars
├── prod.tfvars
├── modules/
│   ├── s3/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   ├── rds/
│   │   ├── main.tf
│   │   ├── variables.tf
│   │   └── outputs.tf
│   └── iam/
│       ├── main.tf
│       ├── variables.tf
│       └── outputs.tf
└── .gitignore
```

---

## Root Module

### `main.tf`

```hcl
terraform {
  required_version = ">= 1.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.0"
    }
  }
}

provider "aws" {
  region = var.aws_region
}

module "s3" {
  source = "./modules/s3"

  bucket_name        = var.bucket_name
  environment        = var.environment
  enable_replication = var.enable_s3_replication
  replica_region     = var.replica_region
  kms_key_id         = var.kms_key_id

  tags = local.tags
}

module "rds" {
  source = "./modules/rds"

  identifier              = var.rds_identifier
  environment             = var.environment
  instance_class          = var.rds_instance_class
  allocated_storage       = var.rds_allocated_storage
  engine_version          = var.rds_engine_version
  multi_az                = var.rds_multi_az
  backup_retention_period = var.rds_backup_retention_days
  db_subnet_group_name    = aws_db_subnet_group.main.name
  db_security_group_ids   = [aws_security_group.rds.id]
  kms_key_id              = var.kms_key_id

  tags = local.tags
}

module "iam" {
  source = "./modules/iam"

  role_name   = var.iam_role_name
  environment = var.environment

  # Grant access to S3 bucket
  s3_bucket_arn = module.s3.bucket_arn

  # Grant access to RDS
  rds_arn = module.rds.rds_arn

  tags = local.tags
}

# VPC infrastructure for RDS (minimal example)
resource "aws_db_subnet_group" "main" {
  name       = "${var.environment}-db-subnet-group"
  subnet_ids = data.aws_subnets.available.ids

  tags = local.tags
}

resource "aws_security_group" "rds" {
  name        = "${var.environment}-rds-sg"
  description = "Security group for RDS"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [data.aws_vpc.default.cidr_block]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = local.tags
}

# Data sources for VPC (using default VPC; replace with custom VPC in production)
data "aws_vpc" "default" {
  default = true
}

data "aws_subnets" "available" {
  filter {
    name   = "vpc-id"
    values = [data.aws_vpc.default.id]
  }
}

locals {
  tags = {
    Environment = var.environment
    ManagedBy   = "Terraform"
    CreatedAt   = timestamp()
  }
}
```

### `variables.tf`

```hcl
variable "aws_region" {
  description = "AWS region"
  type        = string
  default     = "us-east-1"
}

variable "environment" {
  description = "Environment name (dev or prod)"
  type        = string
  validation {
    condition     = can(regex("^(dev|prod)$", var.environment))
    error_message = "Environment must be 'dev' or 'prod'."
  }
}

# S3 Configuration
variable "bucket_name" {
  description = "S3 bucket name"
  type        = string
}

variable "enable_s3_replication" {
  description = "Enable cross-region replication for S3 bucket"
  type        = bool
  default     = false
}

variable "replica_region" {
  description = "Region for S3 replication (prod only)"
  type        = string
  default     = "us-west-2"
}

# RDS Configuration
variable "rds_identifier" {
  description = "RDS instance identifier"
  type        = string
}

variable "rds_instance_class" {
  description = "RDS instance class"
  type        = string
  default     = "db.t3.micro"
}

variable "rds_allocated_storage" {
  description = "Allocated storage in GB"
  type        = number
  default     = 20
}

variable "rds_engine_version" {
  description = "PostgreSQL engine version"
  type        = string
  default     = "14.7"
}

variable "rds_multi_az" {
  description = "Enable Multi-AZ for RDS"
  type        = bool
  default     = false
}

variable "rds_backup_retention_days" {
  description = "Backup retention period in days"
  type        = number
  default     = 7
}

# IAM Configuration
variable "iam_role_name" {
  description = "Name of IAM role for service account"
  type        = string
}

# Encryption
variable "kms_key_id" {
  description = "ARN or ID of KMS key for encryption (optional)"
  type        = string
  default     = null
}
```

### `outputs.tf`

```hcl
output "s3_bucket_id" {
  description = "S3 bucket ID"
  value       = module.s3.bucket_id
}

output "s3_bucket_arn" {
  description = "S3 bucket ARN"
  value       = module.s3.bucket_arn
}

output "rds_endpoint" {
  description = "RDS instance endpoint"
  value       = module.rds.rds_endpoint
  sensitive   = true
}

output "rds_arn" {
  description = "RDS instance ARN"
  value       = module.rds.rds_arn
}

output "iam_role_arn" {
  description = "IAM role ARN"
  value       = module.iam.role_arn
}

output "iam_role_name" {
  description = "IAM role name"
  value       = module.iam.role_name
}
```

