## IAM Module

### `modules/iam/main.tf`

```hcl
# IAM Role for service account (with OIDC for prod)
resource "aws_iam_role" "service" {
  name = var.role_name

  assume_role_policy = var.environment == "prod" ? data.aws_iam_policy_document.assume_role_prod[0].json : data.aws_iam_policy_document.assume_role_dev[0].json

  tags = var.tags
}

# Dev: Standard assume role policy
data "aws_iam_policy_document" "assume_role_dev" {
  count = var.environment == "dev" ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "AWS"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:root"]
    }
    actions = ["sts:AssumeRole"]
  }
}

# Prod: OIDC trust (for IRSA)
data "aws_iam_policy_document" "assume_role_prod" {
  count = var.environment == "prod" ? 1 : 0

  statement {
    effect = "Allow"
    principals {
      type        = "Federated"
      identifiers = ["arn:aws:iam::${data.aws_caller_identity.current.account_id}:oidc-provider/oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE"]
    }
    actions = ["sts:AssumeRoleWithWebIdentity"]
    condition {
      test     = "StringEquals"
      variable = "oidc.eks.us-east-1.amazonaws.com/id/EXAMPLE:sub"
      values   = ["system:serviceaccount:default:app-service"]
    }
  }
}

# Policy for S3 access
resource "aws_iam_role_policy" "s3_access" {
  name   = "${var.role_name}-s3-policy"
  role   = aws_iam_role.service.id
  policy = data.aws_iam_policy_document.s3_access.json
}

data "aws_iam_policy_document" "s3_access" {
  statement {
    effect = "Allow"
    actions = [
      "s3:GetObject",
      "s3:PutObject",
      "s3:DeleteObject"
    ]
    resources = ["${var.s3_bucket_arn}/*"]
  }

  statement {
    effect = "Allow"
    actions = [
      "s3:ListBucket",
      "s3:GetBucketVersioning"
    ]
    resources = [var.s3_bucket_arn]
  }

  # Restrict wildcard actions in prod
  dynamic "statement" {
    for_each = var.environment == "prod" ? [] : [1]
    content {
      effect = "Allow"
      actions = [
        "s3:*"
      ]
      resources = [var.s3_bucket_arn]
    }
  }
}

# Policy for RDS access
resource "aws_iam_role_policy" "rds_access" {
  name   = "${var.role_name}-rds-policy"
  role   = aws_iam_role.service.id
  policy = data.aws_iam_policy_document.rds_access.json
}

data "aws_iam_policy_document" "rds_access" {
  statement {
    effect = "Allow"
    actions = [
      "rds-db:connect"
    ]
    resources = [
      "${var.rds_arn}/*"
    ]
  }

  statement {
    effect = "Allow"
    actions = [
      "secretsmanager:GetSecretValue"
    ]
    resources = [
      "${var.rds_arn}:secret:*"
    ]
  }
}

data "aws_caller_identity" "current" {}
```

